        {match.winner && !tournament.champion && (
          <button type="button" className="control" onClick={nextMatch}>
            Next match
          </button>
        )}
        {!tournament.champion && (
          <button type="button" className="control" onClick={leave}>
            Leave tournament
          </button>
        )}
      </div>
      <TournamentBracket tournament={tournament} />
    </section>
  );
