import { isWon } from '../game.ts';
import type { GameState } from '../game.ts';
import { tournamentPlan } from './pairing.ts';
import type { TournamentMatch, TournamentResult } from './pairing.ts';
import type { Tournament, TournamentPlayer } from './types.ts';

export function normalizeName(draft: string): string {
  return draft.trim().replace(/\s+/gu, ' ').normalize('NFC');
}

export function acceptNames(drafts: readonly string[], count: number): string[] | string {
  if (drafts.length !== count) return 'Choose 4 or 8 players.';
  const names = drafts.map(normalizeName);
  if (names.some((name) => [...name].length < 2 || [...name].length > 20))
    return 'Use 2 to 20 characters.';
  if (new Set(names.map((name) => name.toLowerCase())).size !== count)
    return 'Each name must be different.';
  return names;
}

export function createTournament(
  names: readonly string[],
  boardCodes: readonly string[],
): Tournament | null {
  if (names.length !== 4 && names.length !== 8) return null;
  const players = names.map((name, index) => ({ name, seed: index + 1 }));
  const plan = tournamentPlan(players);
  if (boardCodes.length !== plan.length) return null;
  const matches: TournamentMatch[] = [];
  for (const [index, item] of plan.entries()) {
    const boardCode = boardCodes[index];
    if (!boardCode) return null;
    matches.push({
      boardCode,
      players: item.players,
      results: [null, null],
      round: item.round,
      winner: null,
    });
  }
  return {
    champion: null,
    currentMatch: 0,
    currentTurn: 0,
    game: null,
    matches,
    playerCount: names.length,
    players,
  };
}

export function completeTournamentTurn(tournament: Tournament, game: GameState): Tournament {
  const match = tournament.matches[tournament.currentMatch];
  if (!match || match.winner || match.results[tournament.currentTurn] || !isWon(game))
    return tournament;
  const result: TournamentResult = { elapsedMs: game.elapsedMs, moves: game.moves };
  const results: [TournamentResult | null, TournamentResult | null] =
    tournament.currentTurn === 0 ? [result, match.results[1]] : [match.results[0], result];
  if (tournament.currentTurn === 0) {
    return {
      ...tournament,
      game,
      matches: replaceMatch(tournament.matches, tournament.currentMatch, { ...match, results }),
    };
  }
  const first = match.players[0];
  const second = match.players[1];
  const firstResult = results[0];
  const secondResult = results[1];
  if (!first || !second || !firstResult || !secondResult) return tournament;
  const winner =
    compareTournamentResults(first, firstResult, second, secondResult) <= 0 ? first : second;
  const completed = { ...match, results, winner };
  const matches = replaceMatch(tournament.matches, tournament.currentMatch, completed);
  if (match.round === 'Final') return { ...tournament, champion: winner, game, matches };
  return { ...tournament, game, matches: advanceWinner(matches, tournament.currentMatch, winner) };
}

export function nextTournamentTurn(tournament: Tournament): Tournament {
  const match = tournament.matches[tournament.currentMatch];
  if (
    tournament.currentTurn !== 0 ||
    !match?.results[0] ||
    !tournament.game ||
    !isWon(tournament.game)
  )
    return tournament;
  return { ...tournament, currentTurn: 1, game: null };
}

export function nextTournamentMatch(tournament: Tournament): Tournament {
  const match = tournament.matches[tournament.currentMatch];
  if (
    !match?.winner ||
    tournament.champion ||
    tournament.currentMatch + 1 >= tournament.matches.length
  )
    return tournament;
  return { ...tournament, currentMatch: tournament.currentMatch + 1, currentTurn: 0, game: null };
}

export function compareTournamentResults(
  first: TournamentPlayer,
  firstResult: TournamentResult,
  second: TournamentPlayer,
  secondResult: TournamentResult,
): number {
  return (
    firstResult.moves - secondResult.moves ||
    firstResult.elapsedMs - secondResult.elapsedMs ||
    first.seed - second.seed
  );
}

function replaceMatch(matches: readonly TournamentMatch[], index: number, match: TournamentMatch) {
  return matches.map((entry, position) => (position === index ? match : entry));
}

function advanceWinner(
  matches: readonly TournamentMatch[],
  index: number,
  winner: TournamentPlayer,
): readonly TournamentMatch[] {
  const match = matches[index];
  if (!match) return matches;
  const localIndex = matches.slice(0, index).filter((entry) => entry.round === match.round).length;
  const nextRoundStart = matches.findIndex(
    (entry, position) => position > index && entry.round !== match.round,
  );
  const nextIndex = nextRoundStart + Math.floor(localIndex / 2);
  const next = matches[nextIndex];
  if (!next || nextRoundStart < 0) return matches;
  const players: [TournamentPlayer | null, TournamentPlayer | null] =
    localIndex % 2 === 0 ? [winner, next.players[1]] : [next.players[0], winner];
  return replaceMatch(matches, nextIndex, { ...next, players });
}
import type { TournamentPlayer } from './types.ts';

export type TournamentRound = 'Quarterfinal' | 'Semifinal' | 'Final';

export interface TournamentMatch {
  readonly boardCode: string;
  readonly players: readonly [TournamentPlayer | null, TournamentPlayer | null];
  readonly results: readonly [TournamentResult | null, TournamentResult | null];
  readonly round: TournamentRound;
  readonly winner: TournamentPlayer | null;
}

export interface TournamentResult {
  readonly elapsedMs: number;
  readonly moves: number;
}

interface MatchPlan {
  readonly boardSize: number;
  readonly players: readonly [TournamentPlayer | null, TournamentPlayer | null];
  readonly round: TournamentRound;
}

export function tournamentPlan(players: readonly TournamentPlayer[]): readonly MatchPlan[] {
  const player = (seed: number): TournamentPlayer | null =>
    players.find((entry) => entry.seed === seed) ?? null;
  if (players.length === 4) {
    return [
      { boardSize: 4, players: [player(1), player(4)], round: 'Semifinal' },
      { boardSize: 4, players: [player(2), player(3)], round: 'Semifinal' },
      { boardSize: 8, players: [null, null], round: 'Final' },
    ];
  }
  return [
    { boardSize: 4, players: [player(1), player(8)], round: 'Quarterfinal' },
    { boardSize: 4, players: [player(4), player(5)], round: 'Quarterfinal' },
    { boardSize: 4, players: [player(3), player(6)], round: 'Quarterfinal' },
    { boardSize: 4, players: [player(2), player(7)], round: 'Quarterfinal' },
    { boardSize: 6, players: [null, null], round: 'Semifinal' },
    { boardSize: 6, players: [null, null], round: 'Semifinal' },
    { boardSize: 8, players: [null, null], round: 'Final' },
  ];
}
import { hasExactKeys, isJsonObject, isWithinBytes, parseJson } from '../saved-format.ts';
import { decodeTournamentValue } from './decode.ts';
import { encodeTournament } from './format.ts';
import type { Tournament } from './types.ts';

const TOURNAMENTS_KEY = 'np3:tournaments';
const STORAGE_VERSION = 3;
const MAX_PAST_TOURNAMENTS = 10;
const MAX_STORAGE_BYTES = 262_144;

export interface TournamentStore {
  getItem(key: string): string | null;
  setItem(key: string, value: string): void;
}

interface PastTournamentRead {
  readonly available: boolean;
  readonly tournaments: readonly Tournament[];
}

export function readPastTournaments(store: TournamentStore | null): PastTournamentRead {
  if (!store) return { available: false, tournaments: [] };
  try {
    const text = store.getItem(TOURNAMENTS_KEY);
    if (!text) return { available: true, tournaments: [] };
    if (!isWithinBytes(text, MAX_STORAGE_BYTES)) return { available: true, tournaments: [] };
    const value = parseJson(text);
    if (
      !isJsonObject(value) ||
      !hasExactKeys(value, ['items', 'v']) ||
      value.v !== STORAGE_VERSION ||
      !Array.isArray(value.items)
    )
      return { available: true, tournaments: [] };
    const tournaments: Tournament[] = [];
    for (const item of value.items) {
      const tournament = decodeTournamentValue(item);
      if (!tournament?.champion || tournament.game !== null)
        return { available: true, tournaments: [] };
      tournaments.push(tournament);
    }
    return { available: true, tournaments: tournaments.slice(0, MAX_PAST_TOURNAMENTS) };
  } catch {
    return { available: false, tournaments: [] };
  }
}

export function writePastTournaments(
  store: TournamentStore | null,
  tournaments: readonly Tournament[],
): boolean {
  if (!store) return false;
  try {
    const items = tournaments
      .slice(0, MAX_PAST_TOURNAMENTS)
      .map((tournament) => parseJson(encodeTournament({ ...tournament, game: null })));
    store.setItem(TOURNAMENTS_KEY, JSON.stringify({ items, v: STORAGE_VERSION }));
    return true;
  } catch {
    return false;
  }
}

export function archiveTournament(
  tournaments: readonly Tournament[],
  completed: Tournament,
): Tournament[] {
  const archived = { ...completed, game: null };
  const signature = tournamentSignature(archived);
  return [archived, ...tournaments.filter((item) => tournamentSignature(item) !== signature)].slice(
    0,
    MAX_PAST_TOURNAMENTS,
  );
}

function tournamentSignature(tournament: Tournament): string {
  return `${tournament.players.map((player) => player.name).join('\u0000')}|${tournament.matches
    .map((match) => match.boardCode)
    .join('|')}`;
}
import { decodeTournamentValue } from './decode.ts';
import { findTournamentUnknownField } from './unknown-fields.ts';
import { TOURNAMENT_FORMAT, TOURNAMENT_VERSION } from './format-identity.ts';
import { isWithinBytes, parseJson } from '../saved-format.ts';
import type { Tournament } from './types.ts';

const TOURNAMENT_MAX_BYTES = 65_536;

export function encodeTournament(tournament: Tournament): string {
  return JSON.stringify(
    {
      format: TOURNAMENT_FORMAT,
      tournament: {
        champion: playerValue(tournament.champion),
        currentMatch: tournament.currentMatch,
        currentTurn: tournament.currentTurn,
        game: gameValue(tournament.game),
        matches: tournament.matches.map((match) => ({
          boardCode: match.boardCode,
          players: match.players.map(playerValue),
          results: match.results.map((result) =>
            result ? { elapsedMs: result.elapsedMs, moves: result.moves } : null,
          ),
          round: match.round,
          winner: playerValue(match.winner),
        })),
        playerCount: tournament.playerCount,
        players: tournament.players.map(playerValue),
      },
      version: TOURNAMENT_VERSION,
    },
    null,
    2,
  );
}

export function decodeTournament(text: string): Tournament | null {
  if (!isWithinBytes(text, TOURNAMENT_MAX_BYTES)) return null;
  return decodeTournamentValue(parseJson(text));
}

export function tournamentLoadNotice(text: string): string {
  const value = isWithinBytes(text, TOURNAMENT_MAX_BYTES) ? parseJson(text) : undefined;
  const field = findTournamentUnknownField(value);
  return field ? `Unknown field: ${field}.` : 'Invalid tournament JSON.';
}

function playerValue(player: Tournament['champion']) {
  return player ? { name: player.name, seed: player.seed } : null;
}

function gameValue(game: Tournament['game']) {
  if (!game) return null;
  const selection = game.selection;
  const selectionValue =
    selection.kind === 'closed'
      ? { kind: selection.kind }
      : selection.kind === 'one'
        ? { index: selection.index, kind: selection.kind }
        : {
            first: selection.first,
            kind: selection.kind,
            remainingMs: Math.ceil(selection.remainingMs),
            second: selection.second,
          };
  return {
    boardCode: game.boardCode,
    elapsedMs: Math.floor(game.elapsedMs),
    matched: [...game.matched].sort((left, right) => left - right),
    moves: game.moves,
    selection: selectionValue,
    started: game.started,
    version: 1,
  };
}
import { useEffect, useRef } from 'react';
import { advanceGame, isWon } from '../game.ts';
import { SelectionKind } from '../selection.ts';
import { CLOCK_INTERVAL_MS, createClock, elapsedStep } from '../session/browser-clock.ts';
import type { RefObject } from 'react';
import type { Tournament } from './types.ts';

export function useTournamentClock(
  tournament: Tournament | null,
  enabled: boolean,
  current: RefObject<Tournament | null>,
  commit: (next: Tournament | null) => void,
) {
  const clock = useRef(createClock(performance.now()));
  const visible = useRef(!document.hidden);
  const won = tournament?.game ? isWon(tournament.game) : false;

  function running(): boolean {
    const game = current.current?.game;
    return enabled && visible.current && Boolean(game?.started && !isWon(game));
  }

  function synchronize(): void {
    const now = performance.now();
    const step = elapsedStep(clock.current, now, running());
    clock.current = step.clock;
    const active = current.current;
    if (step.milliseconds && active?.game) {
      const game = advanceGame(active.game, step.milliseconds);
      if (game !== active.game) commit({ ...active, game });
    }
  }

  useEffect(() => {
    clock.current = createClock(performance.now());
  }, [enabled]);

  useEffect(() => {
    const gameGeneration = tournament?.currentMatch;
    let active = true;
    let timer: number | undefined;
    function schedule(): void {
      window.clearTimeout(timer);
      const game = current.current?.game;
      if (!active || !running() || !game) return;
      const delay =
        game.selection.kind === SelectionKind.mismatch
          ? Math.min(CLOCK_INTERVAL_MS, game.selection.remainingMs)
          : CLOCK_INTERVAL_MS;
      timer = window.setTimeout(() => {
        if (!active) return;
        synchronize();
        schedule();
      }, delay);
    }
    function visibilityChanged(): void {
      if (!active || gameGeneration !== current.current?.currentMatch) return;
      synchronize();
      visible.current = !document.hidden;
      schedule();
    }
    schedule();
    document.addEventListener('visibilitychange', visibilityChanged);
    return () => {
      active = false;
      window.clearTimeout(timer);
      document.removeEventListener('visibilitychange', visibilityChanged);
    };
  }, [
    enabled,
    tournament?.currentMatch,
    tournament?.currentTurn,
    tournament?.game?.boardCode,
    tournament?.game?.started,
    won,
  ]);

  return {
    synchronize,
    reset: () => {
      clock.current = createClock(performance.now());
    },
  };
}

import { boardCode, SEED_MAX } from '../deck.ts';

const UINT32_RANGE = 2 ** 32;
const RANDOM_LIMIT = Math.floor(UINT32_RANGE / SEED_MAX) * SEED_MAX;

export function freshBoardCode(
  size: number,
  previousSeed?: number,
  usedCodes: readonly string[] = [],
): string {
  const buffer = new Uint32Array(1);
  for (;;) {
    crypto.getRandomValues(buffer);
    const draw = buffer[0];
    if (draw === undefined || draw >= RANDOM_LIMIT) continue;
    const seed = (draw % SEED_MAX) + 1;
    const code = boardCode(size, seed);
    if (seed !== previousSeed && !usedCodes.includes(code)) return code;
  }
}
import { ELAPSED_MAX_MS, MOVES_MAX } from '../game.ts';
import { decodeSnapshot } from '../snapshot.ts';
import { hasExactKeys, isJsonObject, isNonnegativeSafeInteger } from '../saved-format.ts';
import { TOURNAMENT_FORMAT, TOURNAMENT_VERSION } from './format-identity.ts';
import { normalizeName } from './rules.ts';
import { isValidTournament } from './validation.ts';
import type { TournamentMatch, TournamentResult, TournamentRound } from './pairing.ts';
import type { Tournament, TournamentPlayer } from './types.ts';

const PLAYER_KEYS = ['name', 'seed'];
const RESULT_KEYS = ['elapsedMs', 'moves'];
const MATCH_KEYS = ['boardCode', 'players', 'results', 'round', 'winner'];
const STATE_KEYS = [
  'champion',
  'currentMatch',
  'currentTurn',
  'game',
  'matches',
  'playerCount',
  'players',
];
const ROOT_KEYS = ['format', 'tournament', 'version'];

export function decodeTournamentValue(value: unknown): Tournament | null {
  if (!isJsonObject(value) || !hasExactKeys(value, ROOT_KEYS)) return null;
  if (value.format !== TOURNAMENT_FORMAT || value.version !== TOURNAMENT_VERSION) return null;
  const data = value.tournament;
  if (!isJsonObject(data) || !hasExactKeys(data, STATE_KEYS)) return null;
  const count = data.playerCount;
  if ((count !== 4 && count !== 8) || !Array.isArray(data.players) || data.players.length !== count)
    return null;
  const players = readPlayers(data.players);
  if (!players || new Set(players.map((player) => player.name.toLowerCase())).size !== count)
    return null;
  if (!Array.isArray(data.matches)) return null;
  const matches = readMatches(data.matches);
  if (!matches) return null;
  const champion = readOptionalPlayer(data.champion);
  const game = readGame(data.game);
  if (champion === undefined || game === undefined) return null;
  if (
    !isNonnegativeSafeInteger(data.currentMatch) ||
    (data.currentTurn !== 0 && data.currentTurn !== 1)
  )
    return null;
  const tournament: Tournament = {
    champion,
    currentMatch: data.currentMatch,
    currentTurn: data.currentTurn,
    game,
    matches,
    playerCount: count,
    players,
  };
  return isValidTournament(tournament) ? tournament : null;
}

function readPlayers(values: unknown[]): TournamentPlayer[] | null {
  const players: TournamentPlayer[] = [];
  for (const [index, value] of values.entries()) {
    const player = readPlayer(value);
    if (!player || player.seed !== index + 1) return null;
    players.push(player);
  }
  return players;
}

function readPlayer(value: unknown): TournamentPlayer | null {
  if (!isJsonObject(value) || !hasExactKeys(value, PLAYER_KEYS)) return null;
  if (typeof value.name !== 'string' || !isNonnegativeSafeInteger(value.seed)) return null;
  const name = value.name;
  return name === normalizeName(name) && [...name].length >= 2 && [...name].length <= 20
    ? { name, seed: value.seed }
    : null;
}

function readOptionalPlayer(value: unknown): TournamentPlayer | null | undefined {
  if (value === null) return null;
  return readPlayer(value) ?? undefined;
}

function readResult(value: unknown): TournamentResult | null | undefined {
  if (value === null) return null;
  if (!isJsonObject(value) || !hasExactKeys(value, RESULT_KEYS)) return undefined;
  if (
    !isNonnegativeSafeInteger(value.moves) ||
    value.moves > MOVES_MAX ||
    typeof value.elapsedMs !== 'number' ||
    !Number.isFinite(value.elapsedMs) ||
    value.elapsedMs < 0 ||
    value.elapsedMs > ELAPSED_MAX_MS
  )
    return undefined;
  return { elapsedMs: value.elapsedMs, moves: value.moves };
}

function readMatches(values: unknown[]): TournamentMatch[] | null {
  const matches: TournamentMatch[] = [];
  for (const value of values) {
    const match = readMatch(value);
    if (!match) return null;
    matches.push(match);
  }
  return matches;
}

function readMatch(value: unknown): TournamentMatch | null {
  if (!isJsonObject(value) || !hasExactKeys(value, MATCH_KEYS)) return null;
  const round = readRound(value.round);
  if (typeof value.boardCode !== 'string' || !round) return null;
  if (!Array.isArray(value.players) || value.players.length !== 2) return null;
  if (!Array.isArray(value.results) || value.results.length !== 2) return null;
  const first = readOptionalPlayer(value.players[0]);
  const second = readOptionalPlayer(value.players[1]);
  const firstResult = readResult(value.results[0]);
  const secondResult = readResult(value.results[1]);
  const winner = readOptionalPlayer(value.winner);
  if (
    first === undefined ||
    second === undefined ||
    firstResult === undefined ||
    secondResult === undefined ||
    winner === undefined
  )
    return null;
  return {
    boardCode: value.boardCode,
    players: [first, second],
    results: [firstResult, secondResult],
    round,
    winner,
  };
}

function readRound(value: unknown): TournamentRound | null {
  if (value === 'Quarterfinal' || value === 'Semifinal' || value === 'Final') return value;
  return null;
}

function readGame(value: unknown): Tournament['game'] | undefined {
  if (value === null) return null;
  if (!isJsonObject(value)) return undefined;
  return decodeSnapshot(JSON.stringify(value)) ?? undefined;
}
import { isWon, type GameState } from '../game.ts';
import { parseBoardCode } from '../deck.ts';
import { compareTournamentResults } from './rules.ts';
import { tournamentPlan } from './pairing.ts';
import type { TournamentMatch, TournamentResult } from './pairing.ts';
import type { Tournament, TournamentPlayer } from './types.ts';

export function isValidTournament(tournament: Tournament): boolean {
  const plan = tournamentPlan(tournament.players);
  if (tournament.matches.length !== plan.length || tournament.currentMatch >= plan.length)
    return false;
  const codes = new Set<string>();
  for (const [index, match] of tournament.matches.entries()) {
    const expected = plan[index];
    const parsed = parseBoardCode(match.boardCode);
    if (!expected || !parsed || parsed.size !== expected.boardSize || codes.has(match.boardCode))
      return false;
    codes.add(match.boardCode);
    if (
      match.round !== expected.round ||
      !validParticipants(tournament.matches, plan, index, match)
    )
      return false;
    if (!validMatchResult(match, parsed.size)) return false;
    if (index < tournament.currentMatch && !match.winner) return false;
    if (index > tournament.currentMatch && (match.winner || match.results[0] || match.results[1]))
      return false;
  }
  return validCurrentState(tournament);
}

function validParticipants(
  matches: readonly TournamentMatch[],
  plan: ReturnType<typeof tournamentPlan>,
  index: number,
  match: TournamentMatch,
): boolean {
  const expected = plan[index];
  const firstStage = matches.findIndex((entry) => entry.round !== matches[0]?.round);
  if (!expected) return false;
  if (index < firstStage || firstStage < 0)
    return (
      samePlayer(match.players[0], expected.players[0]) &&
      samePlayer(match.players[1], expected.players[1])
    );
  const stageStart = matches.findIndex(
    (entry, position) => position <= index && entry.round === match.round,
  );
  const previousRound = matches[stageStart - 1]?.round;
  let previousStart = stageStart - 1;
  while (previousStart > 0 && matches[previousStart - 1]?.round === previousRound)
    previousStart -= 1;
  const local = index - stageStart;
  const source0 = matches[previousStart + local * 2];
  const source1 = matches[previousStart + local * 2 + 1];
  return (
    Boolean(source0 && source1) &&
    samePlayer(match.players[0], source0?.winner ?? null) &&
    samePlayer(match.players[1], source1?.winner ?? null)
  );
}

function validMatchResult(match: TournamentMatch, size: number): boolean {
  const [first, second] = match.results;
  if (second && !first) return false;
  for (const result of match.results) {
    if (result && result.moves < (size * size) / 2) return false;
  }
  if (!first || !second) return match.winner === null;
  const player1 = match.players[0];
  const player2 = match.players[1];
  if (!player1 || !player2) return false;
  const expected =
    compareTournamentResults(player1, first, player2, second) <= 0 ? player1 : player2;
  return samePlayer(match.winner, expected);
}

function validCurrentState(tournament: Tournament): boolean {
  const match = tournament.matches[tournament.currentMatch];
  if (!match?.players[0] || !match.players[1]) return false;
  if (tournament.currentTurn === 1 && !match.results[0]) return false;
  const currentResult = match.results[tournament.currentTurn];
  if (tournament.game) {
    if (!validCurrentGame(tournament.game, match, currentResult)) return false;
  } else {
    if (tournament.currentTurn === 0 && match.results[0]) return false;
    if (match.winner && !tournament.champion) return false;
    if (match.results[1] && !tournament.champion) return false;
  }
  return validChampion(tournament, match);
}

function validCurrentGame(
  game: GameState,
  match: TournamentMatch,
  result: TournamentResult | null,
): boolean {
  if (game.boardCode !== match.boardCode) return false;
  if (isWon(game))
    return Boolean(
      result && result.moves === game.moves && Math.floor(result.elapsedMs) === game.elapsedMs,
    );
  return result === null;
}

function validChampion(tournament: Tournament, current: TournamentMatch): boolean {
  const finalMatch = tournament.matches[tournament.matches.length - 1];
  if (!tournament.champion) return current.round !== 'Final' || finalMatch?.winner === null;
  return (
    tournament.currentMatch === tournament.matches.length - 1 &&
    tournament.currentTurn === 1 &&
    samePlayer(tournament.champion, finalMatch?.winner ?? null) &&
    tournament.matches.every((match) => match.winner !== null)
  );
}

function samePlayer(first: TournamentPlayer | null, second: TournamentPlayer | null): boolean {
  return first?.seed === second?.seed && first?.name === second?.name;
}
import { useState } from 'react';

interface TournamentExchangeProps {
  exportData(): string;
  load(text: string): boolean;
}

export function TournamentExchange({ exportData, load }: TournamentExchangeProps) {
  const [text, setText] = useState('');
  return (
    <section className="tournament-exchange" aria-labelledby="tournament-json-heading">
      <h3 id="tournament-json-heading">Tournament JSON</h3>
      <label htmlFor="tournament-json">Tournament JSON</label>
      <textarea
        id="tournament-json"
        className="control"
        rows={5}
        maxLength={65_536}
        spellCheck={false}
        value={text}
        onChange={(event) => setText(event.currentTarget.value)}
      />
      <div className="tournament-actions">
        <button type="button" className="control" onClick={() => setText(exportData())}>
          Export tournament
        </button>
        <button type="button" className="control" onClick={() => load(text)}>
          Load tournament
        </button>
      </div>
    </section>
  );
}
import { useLayoutEffect, useRef } from 'react';

interface LeaveTournamentDialogProps {
  open: boolean;
  loading: boolean;
  confirm(): void;
  cancel(): void;
}

export function LeaveTournamentDialog({
  open,
  loading,
  confirm,
  cancel,
}: LeaveTournamentDialogProps) {
  const dialog = useRef<HTMLDialogElement>(null);
  const keepPlaying = useRef<HTMLButtonElement>(null);

  useLayoutEffect(() => {
    const element = dialog.current;
    if (!element) return;
    if (open && !element.open) {
      element.showModal();
      keepPlaying.current?.focus();
    } else if (!open && element.open) {
      element.close();
    }
  }, [open]);

  return (
    <dialog
      ref={dialog}
      className="tournament-dialog"
      aria-labelledby="leave-tournament-heading"
      onCancel={(event) => {
        event.preventDefault();
        cancel();
      }}
    >
      <h3 id="leave-tournament-heading">
        {loading ? 'Load another tournament?' : 'Leave unfinished tournament?'}
      </h3>
      <p>
        {loading
          ? 'Loading this tournament will replace the current tournament.'
          : 'The current tournament will stop.'}
      </p>
      <div className="tournament-actions">
        <button type="button" className="control" ref={keepPlaying} onClick={cancel}>
          Keep playing
        </button>
        <button type="button" className="control" onClick={confirm}>
          Leave
        </button>
      </div>
    </dialog>
  );
}
